import SearchInterface from '../components/SearchInterface';
import Navigation from '../components/Navigation';
import QuickConnect from '../components/QuickConnect';
import { auth } from '@/auth';
import { redirect } from 'next/navigation';

export default async function Home() {
  const session = await auth();
  if (!session) {
    redirect('/login');
  }

  return (
    <div className="container" style={{ paddingBottom: '4rem' }}>
      <Navigation />

      <main>
        <div style={{textAlign: 'center', margin: '5rem 0 3rem 0', display: 'flex', flexDirection: 'column', alignItems: 'center'}}>
          <div style={{
            background: 'var(--muted-bg)', 
            color: 'var(--foreground)', 
            padding: '0.4rem 1rem', 
            borderRadius: '99px', 
            fontSize: '0.85rem', 
            fontWeight: 600,
            marginBottom: '1.5rem',
            letterSpacing: '0.02em',
            border: '1px solid var(--border)'
          }}>
            V2.0 is Live
          </div>
          <h1 style={{fontSize: '3.5rem', fontWeight: 800, color: 'var(--foreground)', marginBottom: '1rem', lineHeight: 1.1, letterSpacing: '-0.04em'}}>
            CompareAll.
          </h1>
          <p style={{fontSize: '1.2rem', color: 'var(--muted)', maxWidth: '500px', margin: '0 auto 2.5rem auto', letterSpacing: '-0.01em'}}>
            The ultimate universal aggregator. Search once, compare everywhere, and always choose better.
          </p>
        </div>

        <SearchInterface />
        
        <QuickConnect />

      </main>
    </div>
  );
}
